const S=Math.SQRT1_2;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-S,0,0,S],down:[S,0,0,S],left:[0,0,S,S],right:[0,0,-S,S]};
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:'Reach the orange goal square.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const s={...state};
if(dist(s)===0)return s;
const a=event.action;
if(a==='hint'){s.hint=s.c<2?'right':'up';s.msg='Hint: move '+s.hint+' to get one step closer.';return s;}
const d=D[a];if(!d)return s;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=null;
s.msg=dist(s)===0?'You reached the goal in '+s.moves+' moves (shortest is 4).':'Moved '+a+'.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*1.1,z=(1-s.r)*1.1,p=[x,0.35,z];
const n={tok:{position:p},arrow:{visible:!!s.hint,position:p}};
if(s.hint)n.arrow.quaternion=Q[s.hint];
const g=dist(s);
return {nodes:n,readouts:{steps:g,moves:s.moves},goal:{status:g===0?'won':'playing',message:s.msg}};}
